"married":{a:[{tr:"s. evli",ex:"Studies suggest that married couples who share household chores equally report higher levels of satisfaction.",exTr:"Araştırmalar, ev işlerini eşit paylaşan evli çiftlerin daha yüksek memnuniyet düzeyleri bildirdiğini gösteriyor."}]},
"maturation":{a:[{tr:"i. olgunlaşma, olgunluğa erişme",ex:"Psychologists study emotional maturation in adolescents to better understand decision-making during the teenage years.",exTr:"Psikologlar, ergenlik yıllarındaki karar verme sürecini daha iyi anlamak için gençlerdeki duygusal olgunlaşmayı inceler."}]},
"mother-in-law":{a:[{tr:"i. kayınvalide",ex:"She invited her mother-in-law to stay for the entire holiday season this year.",exTr:"Bu yıl kayınvalidesini tüm tatil sezonu boyunca kalması için davet etti."}]},
"no-goal":{a:[{tr:"i. geçersiz sayılan gol, iptal gol",ex:"The referee's no-goal decision sparked outrage among fans who insisted the ball had crossed the line.",exTr:"Hakemin iptal gol kararı, topun çizgiyi geçtiğinde ısrar eden taraftarlar arasında öfkeye yol açtı."}]},
"off-key":{a:[{tr:"s. akort dışı, tonu bozuk (müzikte)",ex:"The nervous singer hit several off-key notes during the audition, despite weeks of careful preparation.",exTr:"Gergin şarkıcı, haftalarca özenli hazırlığa rağmen seçmelerde birkaç akort dışı nota söyledi."}]},
"one-piece":{a:[{tr:"s. tek parça",ex:"Divers usually prefer a one-piece wetsuit because it provides better insulation in colder waters.",exTr:"Dalgıçlar genellikle tek parça bir dalgıç kıyafetini tercih eder çünkü daha soğuk sularda daha iyi yalıtım sağlar."}]},
"out-of-door":{a:[{tr:"s. açık havada yapılan, açık hava (için uygun)",ex:"The summer camp organizes numerous out-of-door activities, including hiking, swimming, and overnight camping trips.",exTr:"Yaz kampı, yürüyüş, yüzme ve gecelik kamp gezileri dahil olmak üzere çok sayıda açık havada etkinlik düzenliyor."}]},
