"pay-phone":{a:[{tr:"i. ankesörlü telefon",ex:"Before mobile phones became common, travelers often relied on a pay-phone to contact their families.",exTr:"Cep telefonları yaygınlaşmadan önce, gezginler ailelerine ulaşmak için sık sık ankesörlü telefona başvururdu."}]},
"pharmacy":{a:[{tr:"i. eczane",ex:"The nearest pharmacy stays open twenty-four hours to serve patients needing urgent prescription medications.",exTr:"En yakın eczane, acil reçeteli ilaca ihtiyaç duyan hastalara hizmet vermek için yirmi dört saat açık kalır."}]},
"pick-me-up":{a:[{tr:"i. canlandırıcı şey (içecek/atıştırmalık)",ex:"A cup of strong coffee in the afternoon serves as a quick pick-me-up before the evening shift.",exTr:"Öğleden sonra içilen güçlü bir fincan kahve, akşam vardiyasından önce hızlı bir canlandırıcı işlevi görür."}]},
"pick-off":{a:[{tr:"i. (beyzbol) koşucuyu kaide dışında yakalayarak eleme",ex:"The shortstop's quick pick-off caught the runner well before he could return safely to first base.",exTr:"Kısa saha oyuncusunun hızlı hareketi, koşucuyu birinci kaideye güvenle dönemeden yakalayıp eledi."}]},
