"policy-making":{a:[{tr:"s. politika belirleyen, karar alma ile ilgili",ex:"Only senior officials are usually included in the country's most important policy-making meetings.",exTr:"Genellikle yalnızca üst düzey yetkililer, ülkenin en önemli politika belirleme toplantılarına dahil edilir."}]},
"prestigious":{a:[{tr:"s. saygın, itibarlı, prestijli",ex:"Only a handful of researchers are invited to present their findings at this prestigious conference each year.",exTr:"Her yıl yalnızca bir avuç araştırmacı, bulgularını bu prestijli konferansta sunmaya davet edilir."}]},
"proximity":{a:[{tr:"i. yakınlık (mekansal, konum bakımından)",ex:"The hotel's proximity to the airport makes it especially popular among business travelers with early flights.",exTr:"Otelin havalimanına yakınlığı, erken uçuşları olan iş seyahati yapan kişiler arasında onu özellikle popüler kılıyor."}]},
"re-start":{a:[{tr:"f. yeniden başlatmak, tekrar başlamak",ex:"Technicians had to re-start the entire server after the unexpected power outage corrupted several files.",exTr:"Teknisyenler, beklenmedik elektrik kesintisi birkaç dosyayı bozduktan sonra tüm sunucuyu yeniden başlatmak zorunda kaldı."}]},
