"double-space":{a:[{tr:"f. çift satır aralığıyla yazmak",ex:"The professor asked students to double-space their essays so comments could be added between lines.",exTr:"Profesör, satırlar arasına yorum eklenebilmesi için öğrencilerden makalelerini çift satır aralığıyla yazmalarını istedi."}]},
"dread":{a:[{tr:"f. -den korkmak, çekinmek",ex:"Many students dread the final exam period more than any other time of the academic year.",exTr:"Birçok öğrenci, akademik yılın diğer herhangi bir döneminden çok final sınavı döneminden korkar.",yz:4},{tr:"i. dehşet, büyük korku",ex:"A sense of quiet dread spread through the village as the storm clouds gathered overhead.",exTr:"Fırtına bulutları tepede toplanırken, köy boyunca sessiz bir dehşet duygusu yayıldı.",yz:2}]},
"drug-free":{a:[{tr:"s. uyuşturucudan arınmış",ex:"The rehabilitation center helps former addicts maintain a drug-free lifestyle through continuous counseling and support.",exTr:"Rehabilitasyon merkezi, eski bağımlıların sürekli danışmanlık ve destek yoluyla uyuşturucudan arınmış bir yaşam tarzını sürdürmesine yardımcı olur."}]},
"dude":{a:[{tr:"i. adam, herif (senli benli hitap)",ex:"The surfer greeted every stranger on the beach with a casual 'hey, dude' and a smile.",exTr:"Sörfçü, plajdaki her yabancıyı rahat bir 'hey, dostum' ve gülümsemeyle selamladı."}]},
"endorse":{a:[{tr:"f. onaylamak, desteklemek",ex:"Several prominent scientists publicly chose to endorse the new international climate agreement last week.",exTr:"Birkaç önde gelen bilim insanı, geçen hafta yeni uluslararası iklim anlaşmasını kamuoyu önünde desteklemeyi tercih etti."}]},
"enlarged":{a:[{tr:"f. enlarge fiilinin geçmiş/V3 biçimi: büyüttü, genişletti",ex:"Farmers enlarged their fields after buying new land.",exTr:"Çiftçiler yeni arazi aldıktan sonra tarlalarını genişletti.",yz:4},{tr:"s. büyümüş, genişlemiş",ex:"The scan revealed an enlarged liver, prompting doctors to order further diagnostic tests immediately.",exTr:"Tarama, büyümüş bir karaciğeri ortaya çıkardı ve bu da doktorları hemen ek tanı testleri istemeye yöneltti.",yz:2}]},
