"self-organization":{a:[{tr:"i. kendi kendine örgütlenme, öz örgütlenme",ex:"Biologists study how ant colonies achieve remarkable self-organization without any single leader directing their behavior.",exTr:"Biyologlar, karınca kolonilerinin davranışlarını yönlendiren tek bir lider olmaksızın nasıl olağanüstü bir kendi kendine örgütlenme sağladığını araştırır."}]},
"self-rule":{a:[{tr:"i. özerklik, kendi kendini yönetme",ex:"The territory finally achieved self-rule after decades of negotiation with the central government.",exTr:"Bölge, merkezi hükümetle onlarca yıl süren müzakerelerin ardından sonunda özerkliğe kavuştu."}]},
"shut-in":{a:[{tr:"i./s. evine bağlı kalmış (kişi), dışarı çıkamayan",ex:"Volunteers deliver groceries every week to elderly shut-in residents who cannot leave their homes.",exTr:"Gönüllüler, evlerinden çıkamayan, evine bağlı kalmış yaşlı sakinlere her hafta market alışverişi teslim eder."}]},
"single-channel":{a:[{tr:"s. tek kanallı",ex:"The old radio only supported single-channel sound, unlike the stereo systems that followed later.",exTr:"Eski radyo, daha sonra ortaya çıkan stereo sistemlerin aksine yalnızca tek kanallı sesi destekliyordu."}]},
"single-foot":{a:[{tr:"i./f. rahvan yürüyüş(ü) (at yürüyüşü)",ex:"Experienced trainers taught the horse to single-foot smoothly across the length of the arena.",exTr:"Deneyimli eğiticiler, atı arenanın boyu boyunca düzgün biçimde rahvan yürümesi için eğitti."}]},
"sinister":{a:[{tr:"s. uğursuz, kötü niyetli",ex:"Something about the abandoned factory's silence felt strangely sinister to the two curious explorers.",exTr:"Terk edilmiş fabrikanın sessizliğindeki bir şey, iki meraklı kâşife tuhaf biçimde uğursuz geldi."}]},
"six-spot":{a:[{tr:"i. altı benekli taş, kart ya da zar yüzü (domino/iskambilde)",ex:"During the game, rolling a six-spot twice in a row gave him an unexpected advantage.",exTr:"Oyun sırasında art arda iki kez zarda altı atması ona beklenmedik bir avantaj sağladı."}]},
"speech-read":{a:[{tr:"f. dudak okumak (sağırlar için)",ex:"Some hard-of-hearing students learn to speech-read in order to follow classroom discussions more easily.",exTr:"Bazı işitme güçlüğü çeken öğrenciler, sınıf tartışmalarını daha kolay takip edebilmek için dudak okumayı öğrenir."}]},
"speed-reading":{a:[{tr:"i. hızlı okuma",ex:"The university library offers a free speed-reading workshop for students preparing for final exams.",exTr:"Üniversite kütüphanesi, final sınavlarına hazırlanan öğrenciler için ücretsiz bir hızlı okuma atölyesi sunuyor."}]},
"sponge":{a:[{tr:"i. sünger",ex:"The nurse gently used a sponge to clean the wound before applying a fresh bandage.",exTr:"Hemşire, temiz bir bandaj uygulamadan önce yarayı temizlemek için nazikçe bir sünger kullandı.",yz:3},{tr:"f. süngerle silmek, emdirmek",ex:"Conservators sponged the ancient fresco with distilled water to remove centuries of accumulated soot.",exTr:"Restoratörler, yüzyıllar boyunca birikmiş kurumu gidermek için kadim freski damıtılmış suyla süngerle sildi.",yz:1}]},
"spot-check":{a:[{tr:"f. rastgele denetlemek, örnekleyerek kontrol etmek",ex:"Inspectors regularly spot-check factory products to ensure they meet national safety standards.",exTr:"Denetçiler, ulusal güvenlik standartlarını karşıladıklarından emin olmak için fabrika ürünlerini düzenli olarak rastgele denetler."}]},
"startle":{a:[{tr:"f. ürkütmek, irkiltmek",ex:"A sudden loud noise from the kitchen startled everyone in the living room.",exTr:"Mutfaktan gelen ani ve yüksek bir ses, oturma odasındaki herkesi irkiltti.",yz:4},{tr:"i. irkilme, ürkme",ex:"The baby gave a sudden startle when the heavy door slammed shut behind the visitors.",exTr:"Ağır kapı ziyaretçilerin arkasından çarparak kapandığında bebek ani bir irkilme yaşadı.",yz:1}]},
"stick-on":{a:[{tr:"s. yapışkanlı, yapıştırma (etiket vb.)",ex:"The warehouse workers applied a stick-on label to every box before shipping it out.",exTr:"Depo çalışanları, her kutuyu göndermeden önce üzerine yapıştırma bir etiket yapıştırdı."}]},
"strong-growing":{a:[{tr:"s. hızlı/güçlü büyüyen (bitki)",ex:"Gardeners favor strong-growing vines to cover the fence quickly during the summer months.",exTr:"Bahçıvanlar, yaz aylarında çiti hızla kaplaması için güçlü büyüyen sarmaşıkları tercih eder."}]},
"strong-smelling":{a:[{tr:"s. keskin kokulu",ex:"The market stalls were filled with strong-smelling spices imported from distant tropical countries.",exTr:"Pazar tezgahları, uzak tropikal ülkelerden ithal edilen keskin kokulu baharatlarla doluydu."}]},
"super-speed":{a:[{tr:"i. süper hız, olağanüstü hız",ex:"The new processor promises super-speed performance that could transform how researchers analyze massive datasets.",exTr:"Yeni işlemci, araştırmacıların devasa veri kümelerini analiz etme biçimini dönüştürebilecek süper hızda bir performans vaat ediyor."}]},
"telecommunication":{a:[{tr:"i. telekomünikasyon, uzaktan iletişim",ex:"Advances in telecommunication technology have made it possible to connect instantly with people across the globe.",exTr:"Telekomünikasyon teknolojisindeki ilerlemeler, dünyanın dört bir yanındaki insanlarla anında bağlantı kurmayı mümkün kıldı."}]},
"test-cross":{a:[{tr:"i. test melezlemesi (genetikte)",ex:"Geneticists performed a test-cross to determine whether the plant's genotype was homozygous or heterozygous.",exTr:"Genetikçiler, bitkinin genotipinin homozigot mu yoksa heterozigot mu olduğunu belirlemek için bir test melezlemesi yaptı."}]},
"titanic":{a:[{tr:"i. the Titanic: Titanik gemisi",ex:"The Titanic disaster led to stricter maritime safety rules.",exTr:"Titanik faciası daha sıkı deniz güvenliği kurallarına yol açtı.",yz:4},{tr:"s. dev gibi, muazzam (büyüklükte)",ex:"Rebuilding the flooded city required a titanic effort from thousands of volunteers and engineers.",exTr:"Sular altında kalan şehri yeniden inşa etmek, binlerce gönüllü ve mühendisten muazzam bir çaba gerektirdi.",yz:2}]},
"top-flight":{a:[{tr:"s. üst düzey, en iyi kalitede",ex:"The university recruited several top-flight researchers to strengthen its new engineering department.",exTr:"Üniversite, yeni mühendislik bölümünü güçlendirmek için birkaç üst düzey araştırmacı işe aldı."}]},
"touch-type":{a:[{tr:"f. on parmak yazmak (klavyeye bakmadan)",ex:"Modern typing courses teach students to touch-type so they can write quickly without looking at the keyboard.",exTr:"Modern klavye kursları, öğrencilere klavyeye bakmadan hızlı yazabilmeleri için on parmak yazmayı öğretir."}]},
"tuberculosis":{a:[{tr:"i. verem, tüberküloz",ex:"Public health workers launched a campaign to reduce tuberculosis rates in overcrowded urban districts.",exTr:"Halk sağlığı çalışanları, aşırı kalabalık kentsel bölgelerde tüberküloz oranlarını azaltmak için bir kampanya başlattı."}]},
"undo":{a:[{tr:"f. geri almak, bozmak, çözmek",ex:"A single careless mistake can undo years of careful planning in a scientific research project.",exTr:"Tek bir dikkatsiz hata, bilimsel bir araştırma projesindeki yıllarca süren özenli planlamayı boşa çıkarabilir."}]},
"ventilation":{a:[{tr:"i. havalandırma",ex:"Poor ventilation in the crowded workshop allowed dust and fumes to accumulate throughout the day.",exTr:"Kalabalık atölyedeki yetersiz havalandırma, toz ve dumanın gün boyunca birikmesine neden oldu."}]},
