"algae":{a:[{tr:"i. algler, su yosunu",ex:"Excess fertilizer running into the lake caused harmful algae to spread rapidly across the surface.",exTr:"Göle karışan fazla gübre, zararlı su yosununun yüzeyde hızla yayılmasına neden oldu."}]},
"ambush":{a:[{tr:"i. pusu",ex:"The patrol walked straight into an ambush that had been prepared near the border crossing.",exTr:"Devriye, sınır geçidi yakınında hazırlanmış bir pusunun tam ortasına düştü.",yz:3},{tr:"f. pusu kurmak, pusuya düşürmek",ex:"The soldiers were warned that rebels might ambush the convoy along the narrow mountain road.",exTr:"Askerler, isyancıların dar dağ yolunda konvoya pusu kurabileceği konusunda uyarıldı.",yz:2}]},
