"cross-eye":{a:[{tr:"i. şaşılık",ex:"The ophthalmologist explained that early treatment can often correct cross-eye in young children.",exTr:"Göz doktoru, erken tedavinin genellikle küçük çocuklarda şaşılığı düzeltebileceğini açıkladı.",yz:3},{tr:"s. şaşı",ex:"Doctors noted that the cross-eyed patient regained normal vision after a simple surgical procedure.",exTr:"Doktorlar, şaşı hastanın basit bir cerrahi işlemden sonra normal görüşünü geri kazandığını kaydetti.",yz:2}]},
"cross-link":{a:[{tr:"i. çapraz bağ",ex:"Chemists strengthened the polymer by introducing additional cross-link bonds between its molecular chains.",exTr:"Kimyagerler, moleküler zincirleri arasına ek çapraz bağlar ekleyerek polimeri güçlendirdi.",yz:3},{tr:"f. çapraz bağlamak",ex:"Manufacturers cross-link the rubber molecules with sulfur to make tyres far more durable under heat.",exTr:"Üreticiler, lastikleri ısı altında çok daha dayanıklı kılmak için kauçuk moleküllerini kükürtle çapraz bağlar.",yz:2}]},
"cross-section":{a:[{tr:"i. enine kesit",ex:"The textbook included a cross-section diagram showing the internal structure of a leaf.",exTr:"Ders kitabı, bir yaprağın iç yapısını gösteren enine kesit bir şema içeriyordu."}]},
"cumulative":{a:[{tr:"s. birikimli, kümülatif",ex:"The cumulative effect of small daily habits can lead to significant improvements in overall health.",exTr:"Küçük günlük alışkanlıkların kümülatif etkisi, genel sağlıkta önemli iyileşmelere yol açabilir."}],es:"accumulated, collective"},
