"custodial":{a:[{tr:"s. gözetim/velayetle ilgili",ex:"The court granted the mother full custodial rights over the children after the lengthy hearing.",exTr:"Mahkeme, uzun süren duruşmanın ardından anneye çocuklar üzerinde tam velayet hakkı verdi."}]},
"dark-brown":{a:[{tr:"s. koyu kahverengi",ex:"The antique table had a rich, dark-brown finish that gave the room a warm atmosphere.",exTr:"Antika masa, odaya sıcak bir hava katan zengin, koyu kahverengi bir kaplamaya sahipti."}]},
"demolished":{a:[{tr:"f. demolish fiilinin geçmiş/V3 biçimi: yıktı, ortadan kaldırdı",ex:"The storm demolished several coastal houses.",exTr:"Fırtına kıyıdaki birkaç evi yıktı.",yz:4},{tr:"s. yıkılmış",ex:"The demolished building was cleared away within a week to make room for the new library.",exTr:"Yıkılan bina, yeni kütüphaneye yer açmak için bir hafta içinde kaldırıldı.",yz:2}]},
