"double-cross":{a:[{tr:"f. ihanet etmek, aldatmak",ex:"The informant decided to double-cross his partners and report the entire scheme to the police.",exTr:"Muhbir, ortaklarına ihanet etmeye ve tüm planı polise bildirmeye karar verdi.",yz:3},{tr:"i. ihanet, aldatmaca",ex:"The novel ends with a stunning double-cross that leaves the reader questioning every earlier chapter.",exTr:"Roman, okuru önceki her bölümü sorgulamaya iten çarpıcı bir ihanetle sona eriyor.",yz:2}]},
"double-double":{a:[{tr:"i. çift-çift performans (basketbol)",ex:"The forward recorded a double-double with twenty points and twelve rebounds in the game.",exTr:"Forvet oyuncusu, maçta yirmi sayı ve on iki ribauntla çift-çift performans elde etti."}]},
