"ill-being":{a:[{tr:"i. mutsuzluk, sağlıksızlık hali",ex:"Researchers linked chronic stress and social isolation to a significant rise in psychological ill-being.",exTr:"Araştırmacılar, kronik stres ve sosyal izolasyonu psikolojik mutsuzluktaki belirgin artışla ilişkilendirdi."}]},
"ill-use":{a:[{tr:"f. kötü davranmak",ex:"The documentary revealed how the factory continued to ill-use its workers despite repeated complaints.",exTr:"Belgesel, fabrikanın tekrarlanan şikâyetlere rağmen işçilerine kötü davranmaya devam ettiğini ortaya koydu."}]},
"ill-used":{a:[{tr:"s. kötü muamele görmüş",ex:"The ill-used tenants finally reported their landlord to the local housing authority.",exTr:"Kötü muamele görmüş kiracılar, sonunda ev sahiplerini yerel konut idaresine şikâyet etti."}]},
"inflated":{a:[{tr:"f. inflate fiilinin geçmiş/V3 biçimi: şişirdi; abarttı",ex:"The device inflated the airbag within milliseconds.",exTr:"Cihaz hava yastığını milisaniyeler içinde şişirdi.",yz:4},{tr:"s. şişirilmiş, abartılı",ex:"Consumers complained that the online store displayed inflated prices right before the holiday sale.",exTr:"Tüketiciler, çevrimiçi mağazanın tatil indiriminden hemen önce şişirilmiş fiyatlar gösterdiğinden şikâyet etti.",yz:2}]},
"influenza":{a:[{tr:"i. grip",ex:"Health officials urged elderly citizens to get vaccinated against influenza before the winter season.",exTr:"Sağlık yetkilileri, kış mevsimi başlamadan önce yaşlı vatandaşları gribe karşı aşı olmaya çağırdı."}]},
