"lady-in-waiting":{a:[{tr:"i. nedime",ex:"The young lady-in-waiting accompanied the queen on all of her official visits abroad.",exTr:"Genç nedime, kraliçeye yurt dışındaki tüm resmi ziyaretlerinde eşlik etti."}]},
"line-shooting":{a:[{tr:"i. hava atma, övüngen konuşma",ex:"Everyone at the reunion recognized his stories as harmless line-shooting rather than genuine achievements.",exTr:"Buluşmadaki herkes, onun hikâyelerini gerçek başarılardan çok zararsız bir hava atma olarak gördü."}]},
"louvre":{a:[{tr:"i. the Louvre: Louvre Müzesi",ex:"The Louvre organised an exhibition devoted to the artist's final works.",exTr:"Louvre, sanatçının son eserlerine ayrılmış bir sergi düzenledi.",yz:4},{tr:"i. panjur kanadı, hava deliği kapağı",ex:"Fresh air entered the workshop through a narrow louvre positioned high on the brick wall.",exTr:"Tuğla duvarın yüksek bir noktasına yerleştirilen dar bir panjur kanadından atölyeye temiz hava giriyordu.",yz:2}]},
"low-budget":{a:[{tr:"s. düşük bütçeli",ex:"The low-budget film unexpectedly became one of the highest-grossing movies of the year.",exTr:"Düşük bütçeli film, beklenmedik biçimde yılın en çok hasılat yapan filmlerinden biri oldu."}]},
