"subscriber":{a:[{tr:"i. abone",ex:"The streaming service gained millions of new subscribers after releasing its most popular series.",exTr:"Yayın hizmeti, en popüler dizisini yayımladıktan sonra milyonlarca yeni aboneye kavuştu."}]},
"supreme":{a:[{tr:"s. en yüksek, üstün",ex:"The general demonstrated supreme confidence in his troops before launching the difficult campaign.",exTr:"General, zorlu harekâtı başlatmadan önce birliklerine karşı üstün bir güven sergiledi."}]},
"surface-to-air":{a:[{tr:"s. yerden havaya",ex:"The military deployed a surface-to-air missile system to defend the coastal region from potential air attacks.",exTr:"Ordu, kıyı bölgesini olası hava saldırılarından korumak için yerden havaya füze sistemi konuşlandırdı."}]},
